function fields(columns: mysql.FieldPacket[]): unknown[][] {
  return columns.map(f => [f.name,f.columnType,f.columnLength,f.flags,f.decimals,f.characterSet,f.schema,f.table,f.orgTable,f.orgName])
}
async function connect() {
  const host = process.env['MYSQL_REFERENCE_HOST']
  const db = host === undefined ? await MySQL.open(':memory:') : undefined
  const conn = await mysql.createConnection(db === undefined ? {host:host as string,user:'root',password:process.env['MYSQL_REFERENCE_PASSWORD'] ?? ''} : {stream:db.createStream(),user:'root'})
  return {db,conn}
}
async function outcome(conn: mysql.Connection, sql: string, method: 'query' | 'execute') {
  await conn.query('DO 0')
  const options = {sql,rowsAsArray:true}
  const [rows,columns] = method === 'query' ? await conn.query(options) : await conn.execute(options)
  const warnings = (await conn.query('SHOW WARNINGS'))[0]
  conn.unprepare(options)
  return [JSON.parse(JSON.stringify(rows)),columns === undefined ? [] : fields(columns),warnings]
}

test('resolved literal diagnostics preserve every byte-valued character through both protocols', async () => {
  const {db,conn} = await connect()
  const values = [...Array.from({length:256},(_,i) => 'G'+String.fromCharCode(i)+'G'),"G'G",'G\\G','G\0\n\r\x1a\t\b\\\'G']
  try {
    for (const [id,value] of values.entries()) for (const [p,prefix] of ['','_utf8mb4','_latin1','_binary'].entries()) for (const [f,fn] of ['UNHEX','INET_ATON','INET6_ATON'].entries()) {
      const sql = 'SELECT '+fn+'('+prefix+mysql.escape(value)+') AS x'
      const expected = [[[null]],FIELDS[METADATA[id]![p*3+f]!],[{Level:'Warning',Code:1411,Message:`Incorrect string value: '${prefix+PRINTED[id]}' for function ${fn.toLowerCase()}`}]]
      for (const method of ['query','execute'] as const) assert.deepEqual(await outcome(conn,sql,method),expected,method+': '+sql)
    }
  } finally {
    await conn.end()
    await db?.end()
  }
})

test('views, checks, generated columns and SHOW CREATE share resolved literal control escaping', async () => {
  const {db,conn} = await connect()
  try {
    await conn.query('CREATE DATABASE literal_controls72')
    await conn.query('USE literal_controls72')
    for (const group of DDL) {
      for (const [sql,method,index] of group) {
        const [rows,columns,warnings] = OUTCOMES[index]!
        assert.deepEqual(await outcome(conn,sql,method),[rows,FIELDS[columns],warnings],method+': '+sql)
      }
      await conn.query('DROP VIEW IF EXISTS v')
      await conn.query('DROP TABLE IF EXISTS t')
    }
  } finally {
    await conn.query('DROP DATABASE IF EXISTS literal_controls72')
    await conn.end()
    await db?.end()
  }
})
